window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q901","domains":[3],"level":5,"tag":"ALL","q":"What is the purpose of Identify Business Analysis Performance Improvements?","opts":["Assess BA work and plan improvements to processes where required","Assess solution performance against business objectives","Approve changes to requirements and designs","Identify potential solution limitations"],"answer":[0],"why":["Correct: this task assesses BA performance and plans process improvements.","This is Solution Evaluation work.","This is Approve Requirements or governance.","This is Assess Solution Limitations or Assess Enterprise Limitations."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q902","domains":[2],"level":1,"tag":"ALL","q":"Which output is prepared to guide an elicitation activity, including its scope, logistics, techniques, and supporting materials?","opts":["Business Analysis Information (communicated)","Elicitation Activity Plan","Elicitation Results (unconfirmed)","Elicitation Results (confirmed)"],"answer":[1],"why":["This results from communicating BA information.","Correct: the Elicitation Activity Plan guides the activity.","These are produced after conducting elicitation.","This results from confirming elicitation information."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61; related: Business Analysis Standard v2 §3 Mindset for Effective Business Analysis, printed pp. 9–12","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q903","domains":[7],"level":2,"tag":"ALL","q":"What is the purpose of Conduct Elicitation?","opts":["Prepare scope, logistics, and techniques for elicitation","Obtain formal approval of requirements","Draw out, explore, and identify information relevant to the change","Confirm information is accurate and consistent"],"answer":[2],"why":["This is Prepare for Elicitation.","This is Approve Requirements.","Correct: elicitation draws out and explores relevant information.","This is Confirm Elicitation Results."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q904","domains":[5],"level":3,"tag":"ALL","q":"Which output results from Confirm Elicitation Results?","opts":["Elicitation Results (unconfirmed)","Requirements (approved)","Business Analysis Information (communicated)","Elicitation Results (confirmed)"],"answer":[3],"why":["This is the output of Conduct Elicitation.","This is the output of Approve Requirements.","This is the output of Communicate Business Analysis Information.","Correct: the task confirms accuracy and consistency of elicitation information."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–67","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q905","domains":[3],"level":4,"tag":"ALL","q":"When is Business Analysis Information (communicated) achieved?","opts":["When target stakeholders understand the information’s content and implications","When the information has merely been sent to all stakeholders","When the information is stored in a repository","When stakeholders formally approve the information"],"answer":[0],"why":["Correct: communication is achieved through shared understanding by the target audience.","Sending alone does not ensure understanding.","Storage supports access but does not itself communicate meaning.","Approval is a distinct decision, not the definition of communicated information."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71; related: Business Analysis Standard v2 §4 Implementing Business Analysis, printed pp. 13–20","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q906","domains":[7],"level":5,"tag":"ALL","q":"Which statement describes Stakeholder Engagement as an output of Manage Stakeholder Collaboration?","opts":["A plan for elicitation activities and logistics","Stakeholders’ willingness to engage in BA activities and interact when needed","A list of stakeholders and their analyzed characteristics","A record of approved requirements and designs"],"answer":[1],"why":["This is an Elicitation Activity Plan.","Correct: this is the Stakeholder Engagement output.","This describes the Stakeholder Engagement Approach.","These are outputs of Approve Requirements."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q907","domains":[3],"level":1,"tag":"ALL","q":"What does Trace Requirements establish and maintain?","opts":["Relative importance of requirements","Approval authority for requirement changes","Relationships among requirements, designs, solution components, and releases","Requirement accuracy and consistency throughout the life cycle"],"answer":[2],"why":["This is Prioritize Requirements.","This is governance and approval planning.","Correct: traceability makes relationships and coverage identifiable.","This is Maintain Requirements."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–83; related: Business Analysis Standard v2 §4.4.3 Tracing Requirements and Designs, printed p. 18","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q908","domains":[3],"level":2,"tag":"ALL","q":"Which outputs are produced by Maintain Requirements?","opts":["Designs (maintained)","Requirements (approved)","Designs (verified)","Requirements (maintained)"],"answer":[0,3],"why":["Correct: maintained designs are an output.","Approved requirements come from Approve Requirements.","Verified designs are associated with Verify Requirements.","Correct: maintained requirements are an output."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; related: Business Analysis Standard v2 §4.4 Requirements and Designs, printed pp. 16–19","multi":true,"sourceSet":"ecba-set-22.html"},{"id":"q909","domains":[5],"level":3,"tag":"ALL","q":"What is the purpose of Prioritize Requirements?","opts":["Rank requirements according to relative importance","Confirm requirements are accurate and consistent","Ensure requirements meet quality standards","Obtain agreement and approval"],"answer":[0],"why":["Correct: prioritization orders requirements by relative importance.","This is Confirm Elicitation Results.","This is Verify Requirements.","This is Approve Requirements."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q910","domains":[5],"level":4,"tag":"ALL","q":"What is the output of Assess Requirements Changes that communicates a recommendation to approve, modify, or deny a proposed change?","opts":["Requirements (traced)","Requirements Change Assessment","Requirements (maintained)","Requirements (approved)"],"answer":[1],"why":["This is an output of Trace Requirements.","Correct: Requirements Change Assessment records the recommendation about a proposed change.","This is an output of Maintain Requirements.","This is an output of Approve Requirements."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–95","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q911","domains":[5],"level":5,"tag":"ALL","q":"Which are inputs to Approve Requirements?","opts":["Governance Approach","Elicitation Results (unconfirmed)","Requirements (verified)","Designs"],"answer":[2,3],"why":["Governance Approach is a guideline/tool, not an input.","Unconfirmed elicitation results are not listed inputs.","Correct: verified requirements are an input.","Correct: Designs ready for further work are an input."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":true,"sourceSet":"ecba-set-22.html"},{"id":"q912","domains":[4,9],"level":1,"tag":"ALL","q":"What is the purpose of Analyze Current State?","opts":["Determine necessary conditions to meet the business need","Choose a change strategy","Assess solution performance measures","Understand why an enterprise needs to change and what the change may affect"],"answer":[3],"why":["This is Define Future State.","This is Define Change Strategy.","This is Measure or Analyze Solution Performance.","Correct: this is the purpose of §6.1."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q913","domains":[4],"level":2,"tag":"ALL","q":"Which is the listed input to Define Future State?","opts":["Business Requirements","Needs","Current State Description","Elicitation Results (confirmed)"],"answer":[0],"why":["Correct: Business Requirements are the listed input to §6.2.","Needs motivate analysis but are not the named input in the task diagram.","Current State Description is a guideline/tool for the task.","Confirmed Elicitation Results are not listed as an input."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q914","domains":[4],"level":3,"tag":"ALL","q":"Which factors are analyzed when assessing a risk?","opts":["Potential time frame when it might occur","Possible consequences if it occurs","Impact of those consequences","Likelihood of the risk"],"answer":[0,1,2,3],"why":["Correct: when the risk may occur is considered.","Correct: potential consequences are analyzed.","Correct: the impact of consequences is analyzed.","Correct: likelihood is assessed."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–124","multi":true,"sourceSet":"ecba-set-22.html"},{"id":"q915","domains":[4],"level":4,"tag":"ALL","q":"What is the purpose of Define Change Strategy?","opts":["Define the future state conditions needed to meet the need","Assess the quality of requirements and designs","Determine the most effective approach to performing the change","Understand the reason the enterprise needs to change"],"answer":[2],"why":["This is Define Future State.","This is Verify Requirements.","Correct: §6.4 selects an approach to perform the change and reach the future state.","This is Analyze Current State."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q916","domains":[5],"level":5,"tag":"ALL","q":"What is the purpose of Specify and Model Requirements?","opts":["Confirm elicitation results for accuracy","Approve requirements for implementation","Trace requirements to solution components","Analyze, synthesize, and refine elicitation results into requirements and designs"],"answer":[3],"why":["This is Confirm Elicitation Results.","This is Approve Requirements.","This is Trace Requirements.","Correct: §7.1 structures and refines elicitation information."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q917","domains":[5],"level":1,"tag":"ALL","q":"Which quality characteristics are used to verify requirements and designs?","opts":["Atomic","Complete","Consistent","Unambiguous"],"answer":[0,1,2,3],"why":["Correct: atomicity is a quality characteristic.","Correct: completeness is a quality characteristic.","Correct: consistency is a quality characteristic.","Correct: unambiguous wording is a quality characteristic."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144","multi":true,"sourceSet":"ecba-set-22.html"},{"id":"q918","domains":[5],"level":2,"tag":"ALL","q":"Which statement best distinguishes Validate Requirements from Verify Requirements?","opts":["Validate traces requirements; Verify maintains them for reuse","Validate assesses alignment with business goals and stakeholder value; Verify checks quality and usability","Validate checks requirement quality; Verify checks business value","Validate obtains approval; Verify confirms elicitation results"],"answer":[1],"why":["Trace and Maintain Requirements are separate tasks.","Correct: validation tests business alignment and value; verification tests quality and usability.","This reverses the task purposes.","Approval and elicitation confirmation are separate tasks."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q919","domains":[5],"level":3,"tag":"ALL","q":"Which are inputs to Define Requirements Architecture?","opts":["Solution Scope","Business Analysis Performance Assessment","Requirements (any state)","Information Management Approach"],"answer":[0,2,3],"why":["Correct: architecture must align with solution boundaries.","Performance Assessment is not a listed input.","Correct: requirements in any state may be included in the architecture.","Correct: this informs storage and access for requirements information."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152","multi":true,"sourceSet":"ecba-set-22.html"},{"id":"q920","domains":[6,8],"level":4,"tag":"ALL","q":"What is the purpose of Define Design Options?","opts":["Estimate the value of each option and recommend one","Ensure requirements collectively support objectives","Measure actual solution performance","Define solution approaches, identify solution components, and represent them in design options"],"answer":[3],"why":["This is Analyze Potential Value and Recommend Solution.","This is Define Requirements Architecture.","This is Measure Solution Performance.","Correct: this describes the purpose of §7.5."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–157","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q921","domains":[6,8],"level":5,"tag":"ALL","q":"Which output is associated with Analyze Potential Value and Recommend Solution?","opts":["Solution Recommendation","Design Options","Potential Value","Requirements (validated)"],"answer":[0],"why":["Correct: Solution Recommendation is the task output.","Design Options are produced by Define Design Options.","Potential Value is an input used as a benchmark when evaluating design options, not an output of §7.6.","Validated requirements are produced by Validate Requirements."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162","multi":true,"sourceSet":"ecba-set-22.html"},{"id":"q922","domains":[6,8],"level":1,"tag":"ALL","q":"What is the purpose of Measure Solution Performance?","opts":["Recommend actions to increase solution value","Determine how well a solution is performing in relation to the value it provides","Analyze trends and variances in collected performance information","Identify internal solution limitations"],"answer":[1],"why":["This is Recommend Actions to Increase Solution Value.","Correct: §8.1 measures solution performance and value delivery.","This is Analyze Performance Measures.","This is Assess Solution Limitations."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q923","domains":[6,8],"level":2,"tag":"ALL","q":"Which aspects are examined when analyzing performance measures?","opts":["Variances between expected and actual performance","Approval status of requirements","Trends","Accuracy and reliability"],"answer":[0,2,3],"why":["Correct: expected-to-actual variances are analyzed.","Requirements approval is not a performance measure analysis element.","Correct: trends are analyzed.","Correct: measurement accuracy and reliability matter."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–173","multi":true,"sourceSet":"ecba-set-22.html"},{"id":"q924","domains":[9],"level":4,"tag":"ALL","q":"Which is the purpose of Assess Enterprise Limitations?","opts":["Determine how factors external to the solution restrict value realization","Determine internal solution factors that restrict value","Measure performance against expected outcomes","Maintain requirements for reuse"],"answer":[0],"why":["Correct: this is the purpose of §8.4.","This is Assess Solution Limitations.","This is Measure Solution Performance.","This is Maintain Requirements."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q925","domains":[8],"level":5,"tag":"ALL","q":"What is the purpose of Recommend Actions to Increase Solution Value?","opts":["Approve requirements and designs","Understand factors creating differences between potential and actual value and recommend a course of action","Assess internal solution limitations only","Assess enterprise limitations only"],"answer":[1],"why":["This is Approve Requirements.","Correct: the task analyzes the gap between potential and actual value and recommends action.","This is Assess Solution Limitations.","This is Assess Enterprise Limitations."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187","multi":false,"sourceSet":"ecba-set-22.html"},{"id":"q926","domains":[3],"level":1,"tag":"ALL","q":"What planning decision is part of organizing business analysis information?","opts":["The level of detail at which information should be captured","Which stakeholders have authority to approve the business case","Which design option must be implemented","How solution performance will be measured after implementation"],"answer":[0],"why":["Correct: information management planning identifies the level of detail to capture.","Approval authority is addressed through governance.","Design options are analyzed in later work.","Performance measurement is addressed in Solution Evaluation."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; related: Business Analysis Standard v2 §4 Implementing Business Analysis, printed pp. 13–20","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q927","domains":[3,9],"level":2,"tag":"ALL","q":"Which guideline can shape the Business Analysis Approach by providing methods, techniques, procedures, concepts, and rules?","opts":["Elicitation Results (confirmed)","Methodologies and Frameworks","Solution Performance Analysis","Requirements Architecture"],"answer":[1],"why":["Confirmed elicitation results are not the named approach-planning guideline.","Correct: Methodologies and Frameworks shape the approach and may be tailored.","Performance analysis informs evaluation, not approach planning.","Requirements Architecture organizes requirements and relationships."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q928","domains":[7],"level":3,"tag":"ALL","q":"Which stakeholder role may require specific representatives or groups to participate in stakeholder engagement?","opts":["Supplier","Tester","Regulator","End User"],"answer":[2],"why":["Suppliers may be external stakeholders but do not hold the described requirement.","Testers provide quality assurance and testability perspectives.","Correct: a Regulator may require specific representatives or groups.","End Users provide perspective on solution use."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q929","domains":[7],"level":4,"tag":"ALL","q":"Which governance element establishes who is responsible for decisions and approvals?","opts":["Information storage and access","Stakeholder characteristics and communication needs","Business analysis task sequencing","Decision-making and approval authority"],"answer":[3],"why":["This is Information Management Approach.","This is Stakeholder Engagement Approach.","This is part of Business Analysis Approach.","Correct: governance defines decision and approval authority."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q930","domains":[3],"level":5,"tag":"ALL","q":"Which output of Identify Business Analysis Performance Improvements records results of assessing BA work?","opts":["Business Analysis Performance Assessment","Solution Performance Analysis","Requirements Change Assessment","Stakeholder Engagement Approach"],"answer":[0],"why":["Correct: the assessment captures analysis of BA performance.","This is produced in Solution Evaluation.","This is produced by Assess Requirements Changes.","This is produced by Plan Stakeholder Engagement."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q931","domains":[7],"level":1,"tag":"ALL","q":"Which guideline/tool helps a business analyst understand relevant stakeholders and their concerns before elicitation?","opts":["Enterprise Limitation","Stakeholder Engagement Approach","Solution Limitation","Requirements (approved)"],"answer":[1],"why":["This is an output of Assess Enterprise Limitations.","Correct: stakeholder engagement information helps plan elicitation participants and approach.","This is an output of Assess Solution Limitations.","Approved requirements are not the guideline named for preparation."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–61","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q932","domains":[7],"level":2,"tag":"ALL","q":"Which stakeholder can often guide the business analyst to appropriate research sources and help arrange experiments or facilitated elicitation?","opts":["Regulator","End User","Domain Subject Matter Expert","Sponsor"],"answer":[2],"why":["Regulators provide compliance perspectives.","End Users provide use and experience information.","Correct: Domain Subject Matter Experts can guide research sources and arrangements.","Sponsors ensure appropriate participation and provide direction."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q933","domains":[5],"level":3,"tag":"ALL","q":"Which method may be used to confirm elicitation results with stakeholders?","opts":["Data Mining","Estimation","Scope Modelling","Reviews"],"answer":[3],"why":["Data Mining identifies patterns from data.","Estimation forecasts effort, cost, or duration.","Scope Modelling defines boundaries.","Correct: Reviews can be used to confirm elicitation results."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–67","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q934","domains":[7],"level":4,"tag":"ALL","q":"Which statement distinguishes formal from informal documentation as communication formats?","opts":["Formal documentation commonly follows organizational templates; informal documentation may be used outside a formal process","Formal documentation is always oral; informal documentation must be stored in a repository","Formal documentation is used only for approval; informal documentation is used only for elicitation","Both formats require a prescribed IIBA template"],"answer":[0],"why":["Correct: the formats differ in formality and whether they follow an organizational process.","This reverses the descriptions.","Both may support communication in different settings.","No single mandated template applies to all communication."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q935","domains":[7],"level":5,"tag":"ALL","q":"Which are elements of Manage Stakeholder Collaboration?","opts":["Approve Requirements","Gain Agreement on Commitments","Monitor Stakeholder Engagement","Collaboration"],"answer":[1,2,3],"why":["Approval is a separate task.","Correct: gaining agreement on commitments is an element.","Correct: monitoring engagement is an element.","Correct: collaboration is an element."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":true,"sourceSet":"ecba-set-23.html"},{"id":"q936","domains":[3],"level":1,"tag":"ALL","q":"Which traceability relationship supports understanding the effect of a proposed change?","opts":["A stakeholder linked only to a meeting schedule","A design option ranked by implementation cost","A requirement linked to related requirements and solution components","A requirement listed without a source or destination"],"answer":[2],"why":["Meeting schedules do not establish requirement traceability.","Ranking options is prioritization or value analysis.","Correct: links among requirements and components support impact analysis.","Without relationships, traceability cannot reveal coverage or effects."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–83; related: Business Analysis Standard v2 §4 Implementing Business Analysis, printed pp. 13–20","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q937","domains":[5],"level":2,"tag":"ALL","q":"How does Maintain Requirements differ from Trace Requirements?","opts":["Maintain establishes relationships; Trace preserves accuracy and reuse","Both tasks approve requirements for implementation","Maintain verifies quality; Trace validates business value","Maintain preserves accuracy and consistency and supports reuse; Trace establishes relationships to other requirements, components, or releases"],"answer":[3],"why":["This reverses their purposes.","Approval is a separate task.","Verify and Validate Requirements are separate tasks.","Correct: this distinguishes the purposes of the two tasks."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q938","domains":[5],"level":3,"tag":"ALL","q":"Which criteria may affect relative requirement priority?","opts":["Benefit","Penalty if not implemented","Cost","Risk"],"answer":[0,1,2,3],"why":["Correct: expected benefit can inform priority.","Correct: consequences of not implementing can affect priority.","Correct: cost is a prioritization consideration.","Correct: risk can influence priority."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91","multi":true,"sourceSet":"ecba-set-23.html"},{"id":"q939","domains":[5],"level":4,"tag":"ALL","q":"What does an Impact Assessment examine when assessing a proposed requirements change?","opts":["Only the cost of implementing the change","The effect of the change on requirements, designs, components, and value","Only the effort to edit the requirement text","Only whether the sponsor agrees with the change"],"answer":[1],"why":["Cost is one consideration, not the only impact.","Correct: impact assessment considers effects across related work products and the change.","Text-edit effort alone is too narrow.","Sponsor input may matter but is not the complete assessment."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–95","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q940","domains":[5],"level":5,"tag":"ALL","q":"Which stakeholder may be responsible for ensuring requirements and designs are supportable within technology standards and organizational capability plans?","opts":["Customer","Regulator","Operational Support","Sponsor"],"answer":[2],"why":["Customers review whether needs are met.","Regulators provide opinions about regulatory compliance.","Correct: Operational Support assesses supportability within these constraints.","The Sponsor is accountable for business outcomes and approval."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q941","domains":[4,9],"level":1,"tag":"ALL","q":"Which output describes enterprise scope, capabilities, resources, performance, culture, dependencies, and infrastructure?","opts":["Solution Limitation","Current State Description","Future State Description","Business Requirements"],"answer":[1,3],"why":["Solution Limitation describes internal constraints and defects in a solution.","Correct: Current State Description records the enterprise context, capabilities, resources, performance, culture, dependencies, and infrastructure.","Future State Description describes proposed future conditions.","Correct: Business Requirements express the problem, opportunity, or constraint identified through current-state understanding."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110","multi":true,"sourceSet":"ecba-set-23.html"},{"id":"q942","domains":[4],"level":2,"tag":"ALL","q":"Which output describes boundaries of proposed new, removed, or modified enterprise components and expected potential value?","opts":["Future State Description may include boundaries and potential value","Current State Description captures existing context only","Future State Description may include desired capabilities, policies, resources, and relationships","A Solution Limitation describes the desired future state"],"answer":[0,2],"why":["Correct: the Future State Description includes proposed components and expected value.","Current State Description describes the existing enterprise.","Correct: the Future State Description may include these desired future-state elements.","Solution Limitation describes constraints and defects in a current solution."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":true,"sourceSet":"ecba-set-23.html"},{"id":"q943","domains":[4],"level":3,"tag":"ALL","q":"Which statements about risk responses are consistent with BABOK Assess Risks?","opts":["Risks can inform selection or coordination of a change strategy","Risks may be accepted when the cost of modifying them or their level outweighs probable loss","Risks are analyzed for consequences, impact, likelihood, and possible timing","Opportunities are always treated as positive risks in BABOK"],"answer":[0,1,2],"why":["Correct: risk assessment informs change strategy decisions.","Correct: a risk may be accepted when addressing it is not justified.","Correct: these are risk analysis dimensions.","BABOK distinguishes opportunities as needs rather than using positive risk for this task."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–124","multi":true,"sourceSet":"ecba-set-23.html"},{"id":"q944","domains":[4],"level":4,"tag":"ALL","q":"Which output captures the selected approach for moving from current state toward future state?","opts":["Current State Description","Requirements Architecture","Change Strategy","Future State Description"],"answer":[2],"why":["This documents the present enterprise context.","This organizes requirements and relationships.","Correct: Change Strategy describes the approach for performing the change.","This describes the desired conditions and boundaries."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q945","domains":[5],"level":5,"tag":"ALL","q":"Which statement about requirements models is accurate?","opts":["Models are only graphical diagrams and cannot include text","Models replace stakeholder requirements after elicitation","Models are created only after solution implementation","Models represent requirements using structured views to improve analysis and communication"],"answer":[3],"why":["Models can include textual and non-graphical forms.","Models do not replace stakeholder needs.","Requirements modeling occurs during analysis, before implementation.","Correct: models provide structured representations that support understanding and communication."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q946","domains":[5],"level":1,"tag":"ALL","q":"Which quality characteristic means a requirement expresses one and only one thing?","opts":["Atomic","Complete","Consistent","Feasible"],"answer":[0],"why":["Correct: atomic requirements express a single thing.","Complete means sufficient information is included.","Consistent means not conflicting with other information.","Feasible means achievable within constraints."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q947","domains":[5],"level":2,"tag":"ALL","q":"Which guideline helps validate that requirements and designs support the business need and future state?","opts":["Requirements (maintained)","Business Objectives","Information Management Approach","Elicitation Activity Plan"],"answer":[1],"why":["This is a maintained work product, not the validation guideline named here.","Correct: Business Objectives help validate alignment with intended outcomes.","This guides storage and access of BA information.","This plans elicitation activities."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q948","domains":[5],"level":3,"tag":"ALL","q":"What does a requirements viewpoint define?","opts":["The approval authority for requirements","The future-state performance target","Conventions for representing, organizing, and relating requirements","A selected design option for implementation"],"answer":[2],"why":["Approval authority is part of governance.","Performance targets are associated with future-state or solution evaluation work.","Correct: a viewpoint establishes conventions for requirements architecture.","A viewpoint is not itself a design option."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q949","domains":[6,8],"level":4,"tag":"ALL","q":"Which output represents a set of possible ways to satisfy the business need?","opts":["Solution Recommendation","Requirements (validated)","Solution Performance Analysis","Design Options"],"answer":[3],"why":["Solution Recommendation results from analyzing and comparing options.","Validated requirements result from validation.","Solution Performance Analysis is part of solution evaluation.","Correct: Design Options describe possible solution approaches."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–157","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q950","domains":[6,8],"level":5,"tag":"ALL","q":"Which are inputs to Analyze Potential Value and Recommend Solution?","opts":["Potential Value","Design Options","Solution Recommendation","Requirements (approved)"],"answer":[0,1],"why":["Correct: Potential Value can be used as a benchmark for evaluating design options.","Correct: Design Options are evaluated and compared to recommend an option.","Solution Recommendation is the task output.","Approved requirements are not listed inputs to this task."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162","multi":true,"sourceSet":"ecba-set-23.html"},{"id":"q951","domains":[6,8],"level":1,"tag":"ALL","q":"What is a solution performance measure used for?","opts":["Assess the quality of each requirement","Assess how well a solution performs and contributes to objectives or value","Define stakeholder approval authority","Trace requirements to releases"],"answer":[1],"why":["This is Verify Requirements.","Correct: performance measures assess solution performance and contribution to objectives.","This is Governance Approach.","This is Trace Requirements."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q952","domains":[6,8],"level":2,"tag":"ALL","q":"Why does BABOK emphasize accuracy when analyzing performance measures?","opts":["Accuracy replaces the need to compare actual and expected results","Performance data is assumed accurate once collected","Inaccurate or unreliable data can invalidate the performance analysis","Accuracy is only needed for financial measures"],"answer":[2],"why":["Variance analysis remains important.","Data must be tested and analyzed for accuracy.","Correct: accuracy and reliability are essential to valid analysis.","All relevant performance data needs to be accurate."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–173","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q953","domains":[6,8],"level":3,"tag":"ALL","q":"Which technique can help identify factors constraining solution performance?","opts":["Data Mining","Root Cause Analysis","Item Tracking","Business Capability Analysis"],"answer":[0,1,2],"why":["Correct: Data Mining can identify factors constraining performance.","Correct: Root Cause Analysis helps identify underlying causes of limitations.","Correct: Item Tracking records and manages issues related to value shortfalls.","Business Capability Analysis is not a technique listed for Assess Solution Limitations."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177","multi":true,"sourceSet":"ecba-set-23.html"},{"id":"q954","domains":[9],"level":4,"tag":"ALL","q":"Which element assesses whether enterprise culture can accept and support a solution?","opts":["Enterprise Culture Assessment","Stakeholder Impact Analysis","Organizational Structure Changes","Operational Assessment"],"answer":[0],"why":["Correct: this element examines cultural understanding, acceptance, and required adjustments.","This examines how the solution affects stakeholder groups.","This assesses effects on formal and informal organizational structure.","This examines the enterprise’s ability to use and support the solution operationally."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q955","domains":[8],"level":5,"tag":"ALL","q":"Which recommendation may result from Recommend Actions to Increase Solution Value?","opts":["Maintain the current solution regardless of performance","Enhance, replace, or retire a solution, or adjust the organization to realize more value","Approve all requirements that were not implemented","Change the original business need to match actual performance"],"answer":[1],"why":["The task may recommend changes or retirement when justified.","Correct: recommendations may include enhancing, replacing, retiring, or making organizational changes.","The task recommends actions based on solution value, not blanket approvals.","The need is not changed merely to fit results."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187","multi":false,"sourceSet":"ecba-set-23.html"},{"id":"q956","domains":[6],"level":1,"tag":"Solution","q":"What is the primary purpose of Specify and Model Requirements?","opts":["Confirm that elicitation results accurately reflect stakeholder information","Analyze, synthesize, and refine elicitation results into requirements and designs","Assess whether requirements support business goals and deliver value","Obtain approval of requirements and designs"],"answer":[1],"why":["That is the purpose of Confirm Elicitation Results.","Correct: §7.1 structures and refines elicitation information into requirements and designs.","That is the purpose of Validate Requirements.","That is the purpose of Approve Requirements."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–141","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q957","domains":[6],"level":2,"tag":"Solution","q":"Which quality characteristic asks whether a requirement can be understood in only one way?","opts":["Feasible","Prioritized","Unambiguous","Validated"],"answer":[2],"why":["Feasibility asks whether the requirement can be implemented within constraints.","Prioritization expresses relative importance.","Correct: an unambiguous requirement has only one interpretation.","Validation concerns alignment with business goals and value."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q958","domains":[6],"level":3,"tag":"Solution","q":"What does validation assess?","opts":["Whether requirements and designs meet quality criteria and are usable","Whether requirements and designs support business goals and deliver potential value","Whether requirements have been approved by the appropriate authority","Whether requirements and designs are maintained consistently over time"],"answer":[1],"why":["That is verification.","Correct: validation checks alignment with business goals and stakeholder value.","That is approval.","That is maintenance."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q959","domains":[6],"level":4,"tag":"Solution","q":"Which inputs are listed for Define Requirements Architecture?","opts":["Requirements (any state)","Solution Scope","Information Management Approach","Business Analysis Performance Assessment"],"answer":[0,1,2],"why":["Correct: requirements in any state may be organized into an architecture.","Correct: the architecture must align with the solution boundaries.","Correct: the information management approach guides how requirements information is represented and managed.","This is not a listed input to this task."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q960","domains":[6],"level":5,"tag":"Solution","q":"Which statement best describes a design option?","opts":["A documented change request awaiting impact analysis","A recommendation selected after comparing expected value","A possible way to satisfy the need, described in terms of solution components and their interactions","A verified requirement approved for implementation"],"answer":[2],"why":["That is a proposed requirements change.","That describes a solution recommendation from §7.6.","Correct: design options describe possible solution approaches and components.","Approval follows verification; it is not a design option."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–157","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q961","domains":[6],"level":1,"tag":"Solution","q":"Which are inputs to Analyze Potential Value and Recommend Solution?","opts":["Design Options","Potential Value","Solution Recommendation","Requirements (approved)"],"answer":[0,1],"why":["Correct: design options are compared to identify the preferred approach.","Correct: potential value is a benchmark for evaluating options.","This is an output of the task.","Approved requirements are not listed as an input to this task."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q962","domains":[6],"level":2,"tag":"Solution","q":"What is the principal output of Analyze Potential Value and Recommend Solution?","opts":["Requirements Architecture","Solution Recommendation","Potential Value","Design Options"],"answer":[1],"why":["Requirements Architecture is produced by §7.4.","Correct: the task compares options and produces a Solution Recommendation.","Potential Value is an input used as a benchmark.","Design Options are produced by §7.5 and used as inputs here."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q963","domains":[6],"level":3,"tag":"Solution","q":"Why are solution performance measures used?","opts":["To determine how well the solution performs and contributes to value","To verify that each requirement is atomic and unambiguous","To establish who may approve requirements","To compare design options before a solution is implemented"],"answer":[0],"why":["Correct: measures show how well a solution performs and contributes to objectives or value.","Those are requirement quality checks in verification.","Approval authority is established through governance.","Design options are compared in §7.6."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q964","domains":[6],"level":4,"tag":"Solution","q":"Which aspects may be examined when analyzing solution performance measures?","opts":["Trends in performance over time","Variances between expected and actual performance","Accuracy and reliability of the measures","Approval status of requirements"],"answer":[0,1,2],"why":["Correct: trends can reveal patterns in solution performance.","Correct: analysis compares actual performance with expected results.","Correct: data accuracy and reliability affect the validity of the analysis.","Requirement approval is managed in Requirements Life Cycle Management."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–173","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q965","domains":[6],"level":5,"tag":"Solution","q":"Which are listed inputs to Assess Solution Limitations?","opts":["Solution Performance Analysis","Implemented Solution (external)","Current State Description","Stakeholder Engagement Approach"],"answer":[0,1],"why":["Correct: performance analysis helps identify factors limiting solution value.","Correct: an external implemented solution can be assessed for limitations.","This is associated with Assess Enterprise Limitations, not a listed input here.","This is not a listed input to this task."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q966","domains":[6],"level":1,"tag":"Solution","q":"What is the focus of Assess Enterprise Limitations?","opts":["Factors within the solution that restrict value","Factors outside the solution that restrict value realization","Whether requirements are suitable for implementation","Whether actual performance matches solution targets"],"answer":[1],"why":["That is the focus of Assess Solution Limitations.","Correct: this task examines enterprise factors external to the solution that constrain value.","That is addressed through verification and approval.","That is examined through solution performance measurement and analysis."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q967","domains":[6],"level":2,"tag":"Solution","q":"Which are possible actions recommended to increase solution value?","opts":["Enhance the solution","Replace or retire the solution","Adjust the organization to realize more value","Approve all requirements regardless of value"],"answer":[0,1,2],"why":["Correct: enhancement may increase value.","Correct: replacement or retirement may be recommended when appropriate.","Correct: organizational changes can improve value realization.","Recommendations are based on assessment, not automatic approval."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q968","domains":[6],"level":3,"tag":"Solution","q":"Which guideline helps assess whether requirements and designs support business objectives?","opts":["Business Objectives","Information Management Approach","Governance Approach","Stakeholder Engagement Approach"],"answer":[0],"why":["Correct: Business Objectives provide a basis for assessing alignment and value.","This guides management of business analysis information.","This guides decision making and approvals.","This guides stakeholder interactions and communications."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q969","domains":[6],"level":4,"tag":"Solution","q":"Which statements describe verification?","opts":["It evaluates requirements and designs against quality characteristics","It determines whether the solution will provide value to stakeholders","It checks whether each requirement and design is understandable and usable","It obtains authorization to proceed with implementation"],"answer":[0,2],"why":["Correct: verification checks quality characteristics.","That is validation.","Correct: verification considers whether requirements and designs can be used effectively.","That is approval."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q970","domains":[6],"level":5,"tag":"Solution","q":"What informs recommendations to increase solution value?","opts":["The gap between potential and actual value","The identified solution and enterprise limitations","A mandatory assumption that the current solution must remain unchanged","Performance information and the causes of value shortfalls"],"answer":[0,1,3],"why":["Correct: recommendations consider value that could be realized versus value delivered.","Correct: limitations can explain shortfalls and point to appropriate actions.","No such assumption is required; replacement or retirement may be considered.","Correct: performance evidence and root causes help shape recommendations."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q971","domains":[9],"level":1,"tag":"Context","q":"What is the purpose of Plan Business Analysis Approach?","opts":["Define how business analysis information is stored and accessed","Determine how business analysis activities will be conducted","Set approval authority for requirements","Assess whether a solution achieves its performance targets"],"answer":[1],"why":["That is Plan Business Analysis Information Management.","Correct: the approach defines an appropriate method for conducting business analysis activities.","That is addressed by governance planning.","That is part of Solution Evaluation."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q972","domains":[9],"level":2,"tag":"Context","q":"Which may be specified in the Business Analysis Approach?","opts":["Activities and deliverables","Timing and sequencing of work","Techniques to be used","Final solution performance results"],"answer":[0,1,2],"why":["Correct: the approach identifies business analysis activities and deliverables.","Correct: it can define timing and sequencing.","Correct: it may specify techniques.","Performance results are gathered during solution evaluation, not planned as approach content."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q973","domains":[9],"level":3,"tag":"Context","q":"What is the purpose of Plan Stakeholder Engagement?","opts":["Analyze stakeholders’ roles, attitudes, and communication needs to plan effective engagement","Define how requirements are represented and related","Determine the expected value of a solution","Set the formal approval status of requirements"],"answer":[0],"why":["Correct: this task analyzes stakeholders and plans an effective engagement approach.","That is Define Requirements Architecture.","Potential value is assessed in Strategy Analysis and solution recommendation.","That is Approve Requirements."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q974","domains":[9],"level":4,"tag":"Context","q":"Which decisions are addressed by a Governance Approach?","opts":["Who has authority to approve requirements and designs","How proposed changes are prioritized for review","How elicitation information is validated with participants","Where analysis information is stored and how it is accessed"],"answer":[0,1],"why":["Correct: governance defines decision-making and approval authority.","Correct: governance can define how decisions and changes are handled.","That belongs to Confirm Elicitation Results.","That is addressed by the Information Management Approach."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–42","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q975","domains":[9],"level":5,"tag":"Context","q":"Which items are addressed by the Information Management Approach?","opts":["How business analysis information is organized and stored","Who may access information and under what controls","How information is maintained and reused","Which design option has the highest potential value"],"answer":[0,1,2],"why":["Correct: organization and storage are part of information management.","Correct: access and control are defined.","Correct: maintenance and reuse are considered.","That is evaluated when analyzing design options."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q976","domains":[9],"level":1,"tag":"Context","q":"What is the purpose of Identify Business Analysis Performance Improvements?","opts":["Assess the performance of business analysis work and identify improvements","Measure the implemented solution against its value targets","Assess the enterprise’s ability to support a solution","Verify requirements against quality characteristics"],"answer":[0],"why":["Correct: this task evaluates BA performance and identifies ways to improve it.","That is Measure Solution Performance.","That is Assess Enterprise Limitations.","That is Verify Requirements."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q977","domains":[9],"level":2,"tag":"Context","q":"Why are requirements traced?","opts":["To show relationships among requirements, designs, solution components, and other work products","To establish whether requirements are sufficiently clear and complete","To obtain formal agreement to implement a requirement","To record whether a solution meets its performance measures"],"answer":[0],"why":["Correct: traceability records relationships and supports impact analysis, coverage, and allocation.","That is verification.","That is approval.","That is solution evaluation."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–83","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q978","domains":[9],"level":3,"tag":"Context","q":"Which are inputs to Maintain Requirements?","opts":["Requirements","Designs","Information Management Approach","Solution Performance Analysis"],"answer":[0,1],"why":["Correct: requirements are maintained through their life cycle.","Correct: designs are also maintained.","This guides the work but is a guideline/tool, not a listed input.","This is not a listed input to Maintain Requirements."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q979","domains":[9],"level":4,"tag":"Context","q":"What is the purpose of Prioritize Requirements?","opts":["Rank requirements and designs according to relative importance","Determine if each requirement is unambiguous","Keep requirements consistent throughout their life cycle","Authorize requirements for implementation"],"answer":[0],"why":["Correct: prioritization ranks requirements and designs by relative importance.","That is verification.","That is maintenance.","That is approval."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q980","domains":[9],"level":5,"tag":"Context","q":"What is documented in a Requirements Change Assessment?","opts":["The impact and recommendation for a proposed change","The stakeholder’s final approval of every requirement","The verified quality characteristics of a design","The approved Information Management Approach"],"answer":[0],"why":["Correct: the assessment records the impact analysis and recommendation to approve, modify, or deny a proposed change.","Formal approval is managed in Approve Requirements.","Verification records quality assessment, not the change recommendation.","The information management approach is not this task’s output."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–95","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q981","domains":[9],"level":1,"tag":"Context","q":"Which are inputs to Approve Requirements?","opts":["Requirements (verified)","Designs (verified)","Governance Approach","Elicitation Results (unconfirmed)"],"answer":[0,1],"why":["Correct: verified requirements are ready for approval.","Correct: verified designs are also inputs.","Governance Approach is a guideline/tool that informs approval, not a listed input.","Unconfirmed elicitation results are not ready for formal approval."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q982","domains":[9],"level":2,"tag":"Context","q":"Which are inputs to Analyze Current State?","opts":["Needs","Elicitation Results","Solution Recommendation","Requirements (approved)"],"answer":[0,1],"why":["Correct: needs motivate analysis of the current state.","Correct: elicitation results inform understanding of the current state.","A recommendation is produced after analysis of options.","Approved requirements are not a listed input to this task."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q983","domains":[9],"level":3,"tag":"Context","q":"Which outputs can be produced by Analyze Current State?","opts":["Current State Description","Business Requirements","Solution Recommendation","Governance Approach"],"answer":[0,1],"why":["Correct: the Current State Description documents relevant enterprise context and capabilities.","Correct: Business Requirements express the business need, problem, opportunity, or constraint.","This is produced by Analyze Potential Value and Recommend Solution.","This is produced by Plan Business Analysis Governance."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q984","domains":[9],"level":4,"tag":"Context","q":"Which statement describes Define Future State?","opts":["It determines the conditions necessary to meet the business need","It approves requirements and designs for implementation","It identifies how stakeholders will participate in analysis","It analyzes actual performance of an implemented solution"],"answer":[0],"why":["Correct: the task defines goals and objectives and the conditions needed to meet the business need.","That is Approve Requirements.","That is Plan Stakeholder Engagement.","That is Solution Evaluation."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119","multi":false,"sourceSet":"ecba-set-24.html"},{"id":"q985","domains":[9],"level":5,"tag":"Context","q":"Which factors are considered when assessing a risk?","opts":["Likelihood that the risk will occur","Potential consequences if it occurs","Impact of those consequences","Whether the risk has already received requirement approval"],"answer":[0,1,2],"why":["Correct: likelihood is considered.","Correct: potential consequences are identified.","Correct: the impact of consequences is assessed.","Requirement approval status is not a risk assessment factor."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–124","multi":true,"sourceSet":"ecba-set-24.html"},{"id":"q986","domains":[6],"level":1,"tag":"Solution","q":"Which outputs may result from Specify and Model Requirements?","opts":["Requirements (specified and modeled)","Designs","Requirements (approved)","Solution Recommendation"],"answer":[0,1],"why":["Correct: requirements may be specified and modeled as an output.","Correct: designs may also be created through analysis and modeling.","Approval is produced by §5.5.","A recommendation is produced by §7.6."],"ref":"BABOK Guide v3 §7.1, printed pp. 136–141","multi":true,"sourceSet":"ecba-set-25.html"},{"id":"q987","domains":[6],"level":2,"tag":"Solution","q":"Which characteristic means that a requirement can be demonstrated through an objective assessment?","opts":["Testable","Consistent","Feasible","Prioritized"],"answer":[0],"why":["Correct: a testable requirement can be assessed objectively.","Consistency means it does not conflict with other requirements.","Feasibility concerns implementability within constraints.","Prioritization expresses relative importance."],"ref":"BABOK Guide v3 §7.2, printed pp. 141–144","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q988","domains":[6],"level":3,"tag":"Solution","q":"Which guideline is used to judge whether requirements and designs align with desired business outcomes?","opts":["Business Objectives","Information Management Approach","Governance Approach","Solution Scope"],"answer":[0],"why":["Correct: Business Objectives provide the basis for assessing alignment and value.","This guides how BA information is managed.","This guides decisions and approvals.","Solution Scope bounds the solution but is not the named alignment guideline."],"ref":"BABOK Guide v3 §7.3, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q989","domains":[6],"level":4,"tag":"Solution","q":"What does a requirements architecture represent?","opts":["The structure and relationships among requirements and designs","The list of authorized approvers for each requirement","The expected performance of an implemented solution","The selected implementation schedule"],"answer":[0],"why":["Correct: it organizes requirements and designs and shows their relationships.","Approval authority is governed through the Governance Approach.","Performance is examined in Solution Evaluation.","Scheduling is part of planning or change implementation."],"ref":"BABOK Guide v3 §7.4, printed pp. 148–152","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q990","domains":[6],"level":5,"tag":"Solution","q":"Which output captures the possible approaches for satisfying the business need?","opts":["Design Options","Requirements Architecture","Requirements Change Assessment","Solution Performance Analysis"],"answer":[0],"why":["Correct: Define Design Options produces possible approaches to meet the need.","This is produced by §7.4.","This is produced by Assess Requirements Changes.","This is produced by Analyze Performance Measures."],"ref":"BABOK Guide v3 §7.5, printed pp. 152–157","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q991","domains":[6],"level":1,"tag":"Solution","q":"When comparing design options, what does Potential Value provide?","opts":["A benchmark for estimating the value each option may deliver","A record of stakeholder approval","A description of the current state","A list of verified requirements"],"answer":[0],"why":["Correct: potential value provides a basis for comparing options and expected benefits.","Approval is handled through governance and §5.5.","Current state is documented in §6.1.","Verified requirements are produced by §7.2."],"ref":"BABOK Guide v3 §7.6, printed pp. 157–162","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q992","domains":[6],"level":2,"tag":"Solution","q":"Which output communicates the recommended design option?","opts":["Solution Recommendation","Design Options","Potential Value","Requirements Architecture"],"answer":[0],"why":["Correct: the task produces the Solution Recommendation.","Options are evaluated inputs to the task.","Potential Value is a comparison benchmark.","Requirements Architecture is produced by §7.4."],"ref":"BABOK Guide v3 §7.6, printed pp. 157–162","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q993","domains":[6],"level":3,"tag":"Solution","q":"What does a performance measure compare or describe?","opts":["An observable aspect of solution performance against a target or desired outcome","The authority assigned to approve a requirement","The relative priority of design options","The relationships among requirements"],"answer":[0],"why":["Correct: measures capture aspects of solution performance and help assess value delivery.","Approval authority is part of governance.","Option comparison is done in §7.6.","Requirements relationships are represented in requirements architecture."],"ref":"BABOK Guide v3 §8.1, printed pp. 166–170","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q994","domains":[6],"level":4,"tag":"Solution","q":"Which findings can emerge from analyzing solution performance measures?","opts":["Trends","Variances between expected and actual results","Data quality or reliability concerns","Stakeholder approval authority"],"answer":[0,1,2],"why":["Correct: trends show performance patterns over time.","Correct: variances identify gaps from expected performance.","Correct: reliability and accuracy affect the conclusions.","Approval authority is defined by governance, not performance analysis."],"ref":"BABOK Guide v3 §8.2, printed pp. 170–173","multi":true,"sourceSet":"ecba-set-25.html"},{"id":"q995","domains":[6],"level":5,"tag":"Solution","q":"Which technique is useful for identifying underlying causes of a solution performance problem?","opts":["Root Cause Analysis","Estimation","Backlog Management","Lessons Learned"],"answer":[0],"why":["Correct: Root Cause Analysis identifies underlying causes of observed problems.","Estimation forecasts effort, cost, or duration.","Backlog Management organizes work items.","Lessons Learned captures experience for future work."],"ref":"BABOK Guide v3 §8.3, printed pp. 173–177","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q996","domains":[6],"level":1,"tag":"Solution","q":"Which limitation is assessed in Assess Enterprise Limitations?","opts":["A constraint arising from the organization or its environment","A defect internal to a solution component","A missing relationship between requirements","A requirement that has not received approval"],"answer":[0],"why":["Correct: enterprise limitations are external factors that constrain value realization.","Internal solution issues belong to Assess Solution Limitations.","Requirements architecture addresses relationships.","Approval is part of Requirements Life Cycle Management."],"ref":"BABOK Guide v3 §8.4, printed pp. 177–182","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q997","domains":[6],"level":2,"tag":"Solution","q":"Which may be recommended to improve value from a solution?","opts":["Enhance or replace the solution","Retire a solution that no longer provides sufficient value","Change organizational practices to support value realization","Approve every outstanding requirement"],"answer":[0,1,2],"why":["Correct: enhancement or replacement may address performance and value gaps.","Correct: retirement may be appropriate when the solution no longer provides value.","Correct: organizational adjustments can increase realized value.","Blanket approval is not a value-based recommendation."],"ref":"BABOK Guide v3 §8.5, printed pp. 182–187","multi":true,"sourceSet":"ecba-set-25.html"},{"id":"q998","domains":[6],"level":3,"tag":"Solution","q":"Which quality characteristic means a requirement contains enough information for its intended use?","opts":["Complete","Modifiable","Prioritized","Validated"],"answer":[0],"why":["Correct: completeness means the requirement has sufficient information for its intended use.","Modifiable means it can be changed without reducing quality.","Prioritized expresses relative importance.","Validation assesses alignment and value."],"ref":"BABOK Guide v3 §7.2, printed pp. 141–144","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q999","domains":[6],"level":4,"tag":"Solution","q":"Which statement distinguishes validation from verification?","opts":["Validation assesses alignment with business goals; verification assesses quality characteristics","Validation approves requirements; verification prioritizes them","Validation traces designs; verification maintains requirements","Validation assesses solution performance; verification measures enterprise limitations"],"answer":[0],"why":["Correct: validation concerns business alignment and value, while verification concerns quality and usability.","Approval and prioritization are separate tasks.","Trace and maintain are separate tasks.","Those are Solution Evaluation activities."],"ref":"BABOK Guide v3 §7.3, printed pp. 144–148","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1000","domains":[6],"level":5,"tag":"Solution","q":"Which evidence is most relevant when recommending action to increase solution value?","opts":["Performance analysis and identified limitations","Potential value and the value actually realized","Requirements approval status alone","The causes of any gap between expected and actual value"],"answer":[0,1,3],"why":["Correct: performance and limitations inform what action may help.","Correct: the comparison between potential and realized value is central.","Approval status alone does not establish whether value is being delivered.","Correct: understanding causes supports a suitable recommendation."],"ref":"BABOK Guide v3 §8.5, printed pp. 182–187","multi":true,"sourceSet":"ecba-set-25.html"},{"id":"q1001","domains":[9],"level":1,"tag":"Context","q":"Which is an output of Plan Business Analysis Approach?","opts":["Business Analysis Approach","Governance Approach","Information Management Approach","Solution Recommendation"],"answer":[0],"why":["Correct: the task establishes the Business Analysis Approach.","Governance Approach is produced by §3.3.","Information Management Approach is produced by §3.4.","Solution Recommendation is produced by §7.6."],"ref":"BABOK Guide v3 §3.1, printed pp. 24–31","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1002","domains":[9],"level":2,"tag":"Context","q":"What is the main purpose of a Stakeholder Engagement Approach?","opts":["Describe how stakeholders will be engaged and communicated with during business analysis","Specify the information storage structure for requirements","Define who approves each change request","Describe the future-state capabilities"],"answer":[0],"why":["Correct: the approach guides stakeholder engagement and communication.","That is the Information Management Approach.","That is part of governance.","That is part of Define Future State."],"ref":"BABOK Guide v3 §3.2, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1003","domains":[9],"level":3,"tag":"Context","q":"Which output establishes the decision-making process and approval authority for business analysis work?","opts":["Governance Approach","Business Analysis Approach","Stakeholder Engagement Approach","Information Management Approach"],"answer":[0],"why":["Correct: governance defines decision-making, change control, and approval authority.","This describes how BA work will be performed.","This describes stakeholder engagement.","This describes information organization and access."],"ref":"BABOK Guide v3 §3.3, printed pp. 37–42","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1004","domains":[9],"level":4,"tag":"Context","q":"Which information management concern addresses protection of business analysis information?","opts":["Access controls and information security","Relative priority of requirements","Solution performance targets","Stakeholder approval status"],"answer":[0],"why":["Correct: access and security controls protect BA information.","Prioritization is covered in §5.3.","Performance targets relate to solution evaluation.","Approval is handled through governance and §5.5."],"ref":"BABOK Guide v3 §3.4, printed pp. 42–47","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1005","domains":[9],"level":5,"tag":"Context","q":"Which activities support identifying business analysis performance improvements?","opts":["Compare actual performance with expected performance","Identify causes of performance gaps","Recommend actions to improve future BA work","Approve a solution design option"],"answer":[0,1,2],"why":["Correct: comparison reveals where performance differs from expectations.","Correct: causes help identify useful improvement actions.","Correct: improvement recommendations are part of the task.","Design option approval is outside BA performance improvement."],"ref":"BABOK Guide v3 §3.5, printed pp. 47–51","multi":true,"sourceSet":"ecba-set-25.html"},{"id":"q1006","domains":[9],"level":1,"tag":"Context","q":"Which is a benefit of tracing requirements?","opts":["Assess the effect of a proposed change on related requirements and designs","Confirm that each requirement is unambiguous","Measure the solution’s realized value","Determine who may approve requirements"],"answer":[0],"why":["Correct: traceability supports impact analysis by showing relationships.","That is verification.","That is Solution Evaluation.","That is governance."],"ref":"BABOK Guide v3 §5.1, printed pp. 79–83","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1007","domains":[9],"level":2,"tag":"Context","q":"What is a central outcome of Maintain Requirements?","opts":["Requirements and designs remain accurate and consistent through their life cycle","Requirements are ranked by relative importance","Requirements are formally authorized for implementation","Requirements are assessed against business objectives"],"answer":[0],"why":["Correct: maintenance preserves accuracy and consistency and supports reuse.","That is Prioritize Requirements.","That is Approve Requirements.","That is Validate Requirements."],"ref":"BABOK Guide v3 §5.2, printed pp. 83–86","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1008","domains":[9],"level":3,"tag":"Context","q":"Which factor may be used when prioritizing requirements?","opts":["Business value","Risk","Dependencies among requirements","Whether the requirement appears first alphabetically"],"answer":[0,1,2],"why":["Correct: value is commonly considered in prioritization.","Correct: risk can affect priority.","Correct: dependencies can affect sequencing and priority.","Alphabetical order alone is not a meaningful prioritization factor."],"ref":"BABOK Guide v3 §5.3, printed pp. 86–91","multi":true,"sourceSet":"ecba-set-25.html"},{"id":"q1009","domains":[9],"level":4,"tag":"Context","q":"What does Assess Requirements Changes determine?","opts":["The impact of a proposed change and a recommendation about it","Whether all requirements are complete and testable","Whether the current solution should be retired","How BA information is stored"],"answer":[0],"why":["Correct: the task assesses impacts and recommends approval, modification, or denial.","That is verification.","That is considered in Recommend Actions to Increase Solution Value.","That is Plan Business Analysis Information Management."],"ref":"BABOK Guide v3 §5.4, printed pp. 91–95","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1010","domains":[9],"level":5,"tag":"Context","q":"What does approval of requirements and designs signify?","opts":["Stakeholders have authorized them to be used as a basis for further work","They have been prioritized against all business needs","They have been proven to deliver actual solution value","They have been maintained for reuse"],"answer":[0],"why":["Correct: approval records agreement and authorization for subsequent work.","Prioritization is a distinct task.","Actual value is assessed after solution implementation.","Maintenance keeps requirements accurate and reusable."],"ref":"BABOK Guide v3 §5.5, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1011","domains":[9],"level":1,"tag":"Context","q":"Which deliverable describes the relevant current conditions, capabilities, and context of the enterprise?","opts":["Current State Description","Future State Description","Solution Recommendation","Stakeholder Engagement Approach"],"answer":[0],"why":["Correct: the Current State Description captures relevant present conditions and capabilities.","This is defined in §6.2.","This is produced in §7.6.","This is produced in §3.2."],"ref":"BABOK Guide v3 §6.1, printed pp. 103–110","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1012","domains":[9],"level":2,"tag":"Context","q":"Which is an objective of defining the future state?","opts":["Establish measurable goals and objectives for the change","Record all confirmed elicitation results","Approve the requirements architecture","Assess the accuracy of solution performance data"],"answer":[0],"why":["Correct: the future state defines goals, objectives, and measurable outcomes.","That is Confirm Elicitation Results.","Requirements Architecture is defined in §7.4.","That is part of analyzing performance measures."],"ref":"BABOK Guide v3 §6.2, printed pp. 110–119","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1013","domains":[9],"level":3,"tag":"Context","q":"Which risk attribute expresses how likely a risk is to occur?","opts":["Probability or likelihood","Impact","Consequence","Priority of a requirement"],"answer":[0],"why":["Correct: probability or likelihood describes the chance that the risk will occur.","Impact describes the effect if it occurs.","A consequence is an outcome of the risk occurring.","Requirement priority is assessed in §5.3."],"ref":"BABOK Guide v3 §6.3, printed pp. 120–124","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1014","domains":[9],"level":4,"tag":"Context","q":"Which output describes the selected approach for moving from the current state toward the future state?","opts":["Change Strategy","Current State Description","Requirements Architecture","Requirements Change Assessment"],"answer":[0],"why":["Correct: the Change Strategy outlines the approach to achieving the future state.","This is produced by §6.1.","This is produced by §7.4.","This is produced by §5.4."],"ref":"BABOK Guide v3 §6.4, printed pp. 124–131","multi":false,"sourceSet":"ecba-set-25.html"},{"id":"q1015","domains":[9],"level":5,"tag":"Context","q":"Which issues should be considered when selecting a change strategy?","opts":["The desired future state and the gap from current state","Enterprise readiness and constraints","Risk and transition considerations","The current approval status of unrelated requirements"],"answer":[0,1,2],"why":["Correct: the strategy must bridge the current and desired states.","Correct: readiness and constraints affect the viable approach.","Correct: risks and transition needs shape the strategy.","Unrelated approval status is not a change-strategy criterion."],"ref":"BABOK Guide v3 §6.4, printed pp. 124–131","multi":true,"sourceSet":"ecba-set-25.html"},{"id":"q1016","domains":[4],"level":1,"tag":"Change","q":"A retailer replaces separate online and in-store inventory systems with one shared platform. In BACCM terms, what is the change?","opts":["The transformation from the current way of working to the new way","The shared inventory platform itself","The financial benefit expected by store managers","The sales forecasting problem that prompted the work"],"answer":[0],"why":["Correct: Change is the transformation in response to a need.","This is the Solution.","This describes potential Value.","This is the Need."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23; §6.4 Define Change Strategy, pp. 124–131","multi":false,"sourceSet":"ecba-set-26.html"},{"id":"q1017","domains":[4],"level":2,"tag":"Change","q":"Which statements are true of Change in the BACCM?","opts":["It may be evaluated in terms of its impact on the enterprise","It is a transformation in response to a need","It may be planned or emergent","It is always limited to technology implementation"],"answer":[0,1,2],"why":["Correct: change affects the enterprise and can be assessed for its impacts.","Correct: this is the BACCM definition of Change.","Correct: change may be planned or emerge in response to events.","Change can involve people, processes, structures, policies, or technology."],"ref":"BABOK Guide v3 §2.4 BACCM, printed pp. 14–23","multi":true,"sourceSet":"ecba-set-26.html"}]);